+const transactionalReloadStateFilename = "transactional-reload-state.json"
+
+// transactionalReload manages config application as an all-or-diagnosable attempt.
+// The last known good configuration is deliberately kept only in memory: it is
+// always initialized from the successfully loaded startup configuration.
+type transactionalReload struct {
+	filename              string
+	enableExemplarStorage bool
+	storageDir            string
+	logger                *slog.Logger
+	noStepSubqueryInterval *safePromQLNoStepSubqueryInterval
+	reloaders             []reloader
+
+	mu            sync.RWMutex
+	lastKnownGood *config.Config
+	status        api_v1.ReloadStatus
+}
+
+func newTransactionalReload(filename string, enableExemplarStorage bool, storageDir string, logger *slog.Logger, noStepSubqueryInterval *safePromQLNoStepSubqueryInterval, reloaders []reloader) *transactionalReload {
+	t := &transactionalReload{
+		filename: filename, enableExemplarStorage: enableExemplarStorage, storageDir: storageDir,
+		logger: logger, noStepSubqueryInterval: noStepSubqueryInterval, reloaders: reloaders,
+		status: emptyReloadStatus(),
+	}
+	t.loadStatus()
+	return t
+}
+
+func emptyReloadStatus() api_v1.ReloadStatus {
+	return api_v1.ReloadStatus{ErrorCategory: "none", AppliedReloaders: []string{}, ReloaderTimingsMS: map[string]float64{}}
+}
+
+func (t *transactionalReload) Status() api_v1.ReloadStatus {
+	t.mu.RLock()
+	defer t.mu.RUnlock()
+	return cloneReloadStatus(t.status)
+}
+
+func cloneReloadStatus(s api_v1.ReloadStatus) api_v1.ReloadStatus {
+	s.AppliedReloaders = append([]string{}, s.AppliedReloaders...)
+	s.ReloaderTimingsMS = make(map[string]float64, len(s.ReloaderTimingsMS))
+	for name, timing := range s.ReloaderTimingsMS {
+		s.ReloaderTimingsMS[name] = timing
+	}
+	return s
+}
+
+// Load applies the startup config and makes it available for future rollback.
+// Startup is not a reload attempt, so it intentionally does not persist status.
+func (t *transactionalReload) Load(callback func(bool)) error {
+	return t.reload(true, callback)
+}
+
+func (t *transactionalReload) Reload(callback func(bool)) error {
+	return t.reload(false, callback)
+}
+
+func (t *transactionalReload) reload(initial bool, callback func(bool)) (err error) {
+	t.logger.Info("Loading configuration file", "filename", t.filename)
+	conf, err := config.LoadFile(t.filename, agentMode, t.logger)
+	if err != nil {
+		if !initial {
+			t.record(api_v1.ReloadStatus{
+				LastReloadID: time.Now().UTC().Format(time.RFC3339Nano), ErrorCategory: "load_error", ErrorMessage: err.Error(),
+				AppliedReloaders: []string{}, ReloaderTimingsMS: map[string]float64{},
+			})
+		}
+		callback(false)
+		return fmt.Errorf("couldn't load configuration (--config.file=%q): %w", t.filename, err)
+	}
+	if t.enableExemplarStorage && conf.StorageConfig.ExemplarsConfig == nil {
+		conf.StorageConfig.ExemplarsConfig = &config.DefaultExemplarsConfig
+	}
+
+	status := emptyReloadStatus()
+	status.LastReloadID = time.Now().UTC().Format(time.RFC3339Nano)
+	for _, rl := range t.reloaders {
+		started := time.Now()
+		err = rl.reloader(conf)
+		status.ReloaderTimingsMS[rl.name] = float64(time.Since(started)) / float64(time.Millisecond)
+		if err != nil {
+			status.ErrorCategory = "apply_error"
+			status.ErrorMessage = err.Error()
+			status.FailedReloader = rl.name
+			break
+		}
+		status.AppliedReloaders = append(status.AppliedReloaders, rl.name)
+	}
+
+	if err == nil {
+		updateGoGC(conf, t.logger)
+		t.noStepSubqueryInterval.Set(conf.GlobalConfig.EvaluationInterval)
+		t.mu.Lock()
+		t.lastKnownGood = conf
+		t.mu.Unlock()
+		if !initial {
+			status.LastReloadSuccessful = true
+			status.ErrorCategory = "none"
+			t.record(status)
+		}
+		configSuccess.Set(1)
+		configSuccessTime.SetToCurrentTime()
+		callback(true)
+		return nil
+	}
+
+	if len(status.AppliedReloaders) > 0 {
+		status.RollbackAttempted = true
+		if rollbackErr := t.rollback(); rollbackErr != nil {
+			status.ErrorCategory = "rollback_error"
+			status.ErrorMessage = fmt.Sprintf("failed to apply configuration with %s: rollback failed: %v", status.FailedReloader, rollbackErr)
+		} else {
+			status.RollbackSuccessful = true
+		}
+	}
+	if !initial {
+		t.record(status)
+	}
+	configSuccess.Set(0)
+	callback(false)
+	return fmt.Errorf("one or more errors occurred while applying the new configuration (--config.file=%q)", t.filename)
+}
+
+func (t *transactionalReload) rollback() error {
+	t.mu.RLock()
+	conf := t.lastKnownGood
+	t.mu.RUnlock()
+	if conf == nil {
+		return fmt.Errorf("no known-good configuration is available")
+	}
+	for _, rl := range t.reloaders {
+		if err := rl.reloader(conf); err != nil {
+			return fmt.Errorf("%s: %w", rl.name, err)
+		}
+	}
+	updateGoGC(conf, t.logger)
+	t.noStepSubqueryInterval.Set(conf.GlobalConfig.EvaluationInterval)
+	return nil
+}
+
+func (t *transactionalReload) record(status api_v1.ReloadStatus) {
+	t.mu.Lock()
+	t.status = cloneReloadStatus(status)
+	t.mu.Unlock()
+	if err := t.persistStatus(status); err != nil {
+		t.logger.Warn("Failed to persist transactional reload status", "err", err)
+	}
+}
+
+func (t *transactionalReload) statePath() string { return filepath.Join(t.storageDir, transactionalReloadStateFilename) }
+
+func (t *transactionalReload) persistStatus(status api_v1.ReloadStatus) error {
+	if err := os.MkdirAll(t.storageDir, 0o755); err != nil {
+		return err
+	}
+	b, err := json.Marshal(status)
+	if err != nil {
+		return err
+	}
+	tmp := t.statePath() + ".tmp"
+	if err := os.WriteFile(tmp, b, 0o644); err != nil {
+		return err
+	}
+	return os.Rename(tmp, t.statePath())
+}
+
+func (t *transactionalReload) loadStatus() {
+	b, err := os.ReadFile(t.statePath())
+	if err != nil {
+		if !os.IsNotExist(err) {
+			t.logger.Warn("Failed to read transactional reload status", "err", err)
+		}
+		return
+	}
+	var status api_v1.ReloadStatus
+	if err := json.Unmarshal(b, &status); err != nil || !validReloadStatus(status) {
+		if err != nil {
+			t.logger.Warn("Ignoring corrupt transactional reload status", "err", err)
+		} else {
+			t.logger.Warn("Ignoring invalid transactional reload status")
+		}
+		return
+	}
+	if status.AppliedReloaders == nil {
+		status.AppliedReloaders = []string{}
+	}
+	if status.ReloaderTimingsMS == nil {
+		status.ReloaderTimingsMS = map[string]float64{}
+	}
+	t.status = status
+}
+
+func validReloadStatus(status api_v1.ReloadStatus) bool {
+	switch status.ErrorCategory {
+	case "none", "load_error", "apply_error", "rollback_error":
+		return true
+	default:
+		return false
+	}
+}
